using System;
using System.IO;
using System.Linq;
using System.Collections.Generic;
using UnityEngine;
using UnityEditor;
public static class Native67FloatGpuReview {
 const int N=994452;
 [Serializable] public class Pose {public string clip;public float seconds;public double maxErrorM,maxLocalError;public int worstOriginalId;public float maxRestDisplacementM;public Vector3 worldSpan;public Matrix4x4 meshLocalToWorld;}
 [Serializable] public class Report {public string status="RUNNING_NO_ACCEPTANCE",error,device,api,unity;public bool gpuInputWeightsBitExact,allPositive;public int positiveCoefficients,maxInfluences,vertices;public float smallestPositive;public List<Pose> poses=new List<Pose>(); public string limits="Numeric positions vs CPU double accumulation of actual sampled Unity Float32 skin matrices; errors transformed to world metres. Original Blender offkey oracle equivalence remains separate. Numeric positions only. No normals/tangents/render/material/performance/mobile acceptance. No production writes.";}
 static T[] Read<T>(string p,int bytes) where T:struct{var b=File.ReadAllBytes(p);var a=new T[b.Length/bytes];Buffer.BlockCopy(b,0,a,0,b.Length);return a;}
 public static void Run(){var r=new Report{device=SystemInfo.graphicsDeviceName,api=SystemInfo.graphicsDeviceType.ToString(),unity=Application.unityVersion};var buffers=new List<ComputeBuffer>();GameObject instance=null;int exit=1;
 try {
 if(!SystemInfo.supportsComputeShaders)throw new Exception("Actual compute GPU required");
 string prior=Environment.GetEnvironmentVariable("LF_NATIVE67_GEOMETRY_REPORT");string proof=File.ReadAllText(prior);foreach(string gate in new[]{"allOriginalIds","allTriangles","allCornerUV","positionsVerified"})if(!proof.Contains("\""+gate+"\": true"))throw new Exception("Full geometry gate not verified "+gate);
 string packet=Environment.GetEnvironmentVariable("LF_NATIVE67_PACKET");var counts=File.ReadAllBytes(packet+"/counts.bin");var sourceIndices=Read<int>(packet+"/indices.bin",4);var weights=Read<float>(packet+"/weights.bin",4);var names=File.ReadAllLines(packet+"/bones.txt");var offsets=new int[N+1];for(int i=0;i<N;i++)offsets[i+1]=offsets[i]+counts[i];if(offsets[N]!=2922048||weights.Length!=offsets[N]||weights.Any(w=>!(w>0)))throw new Exception("Full-positive source shape");
 string asset="Assets/Native67SpatialReview/SailorReview.fbx";instance=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<GameObject>(asset));var skin=instance.GetComponentsInChildren<SkinnedMeshRenderer>(true).Single();var ids=SailorNative67SpatialImportReview.ReadSourceVertexIds(skin.sharedMesh,new SailorNative67SpatialImportReview.SourceIndexLayerContract{layerName="__LF_SOURCE_VERTEX_ID_V1",originalVertexCount=N,denominator=1048576,originalUVLayerNames=new[]{"UVMap"},exportUVLayerOrder=new[]{"UVMap","__LF_SOURCE_VERTEX_ID_V1"},manifestCandidateChannel=1,verifiedImportedV=0});var vv=skin.sharedMesh.vertices;var p=new Vector4[N];var seen=new bool[N];for(int i=0;i<ids.Length;i++){int id=ids[i];if(!seen[id]){seen[id]=true;p[id]=new Vector4(vv[i].x,vv[i].y,vv[i].z,1);}}
 var boneMap=skin.bones.Select((b,i)=>new{b.name,i}).ToDictionary(b=>b.name,b=>b.i);var indices=sourceIndices.Select(i=>boneMap[names[i]]).ToArray();var binds=skin.sharedMesh.bindposes;
 Func<int,int,ComputeBuffer> buf=(n,s)=>{var b=new ComputeBuffer(n,s,ComputeBufferType.Structured);buffers.Add(b);return b;};var bp=buf(N,16);bp.SetData(p);var bo=buf(offsets.Length,4);bo.SetData(offsets);var bi=buf(indices.Length,4);bi.SetData(indices);var bw=buf(weights.Length,4);bw.SetData(weights);var br=buf(67*3,16);var bout=buf(N,16);
 var copied=new float[weights.Length];bw.GetData(copied);r.gpuInputWeightsBitExact=true;for(int i=0;i<copied.Length;i++)if(BitConverter.SingleToInt32Bits(copied[i])!=BitConverter.SingleToInt32Bits(weights[i]))throw new Exception("GPU Float32 source coefficient changed "+i);r.allPositive=copied.All(w=>w>0);r.positiveCoefficients=weights.Length;r.smallestPositive=copied.Min();r.maxInfluences=counts.Max();r.vertices=N;
 var cs=AssetDatabase.LoadAssetAtPath<ComputeShader>("Assets/Native67SpatialReview/Shaders/Native67FullFloatReview.compute");if(cs==null)throw new Exception("Compute asset missing");int kernel=cs.FindKernel("Skin");cs.SetInt("_Count",N);cs.SetBuffer(kernel,"_Positions",bp);cs.SetBuffer(kernel,"_Offsets",bo);cs.SetBuffer(kernel,"_BoneIndices",bi);cs.SetBuffer(kernel,"_Weights",bw);cs.SetBuffer(kernel,"_Rows",br);cs.SetBuffer(kernel,"_Output",bout);
 var clips=AssetDatabase.LoadAllAssetsAtPath(asset).OfType<AnimationClip>().Where(c=>!c.name.StartsWith("__preview__")).ToArray();string[] semantics={"box_02","box_02","dance_01","dance_01","front_kick_01"};float[] phase={.35f,.70f,.45f,.50f,.35f};var output=new Vector4[N];
 for(int pose=0;pose<semantics.Length;pose++){var clip=clips.Single(c=>c.name.EndsWith("|"+semantics[pose]));float t=clip.length*phase[pose];clip.SampleAnimation(instance,t);var matrices=new Matrix4x4[67];var rows=new Vector4[67*3];for(int b=0;b<67;b++){matrices[b]=skin.transform.worldToLocalMatrix*skin.bones[b].localToWorldMatrix*binds[b];for(int j=0;j<3;j++)rows[b*3+j]=matrices[b].GetRow(j);}br.SetData(rows);cs.Dispatch(kernel,(N+255)/256,1,1);bout.GetData(output);var pr=new Pose{clip=semantics[pose],seconds=t,meshLocalToWorld=skin.transform.localToWorldMatrix};var lo=new Vector3(float.PositiveInfinity,float.PositiveInfinity,float.PositiveInfinity);var hi=new Vector3(float.NegativeInfinity,float.NegativeInfinity,float.NegativeInfinity);
 for(int v=0;v<N;v++){double x=0,y=0,z=0;var q=p[v];for(int k=offsets[v];k<offsets[v+1];k++){var m=matrices[indices[k]];double w=weights[k];x+=w*((double)m.m00*q.x+(double)m.m01*q.y+(double)m.m02*q.z+m.m03);y+=w*((double)m.m10*q.x+(double)m.m11*q.y+(double)m.m12*q.z+m.m13);z+=w*((double)m.m20*q.x+(double)m.m21*q.y+(double)m.m22*q.z+m.m23);}var got=output[v];double dx=got.x-x,dy=got.y-y,dz=got.z-z;double local=Math.Sqrt(dx*dx+dy*dy+dz*dz);pr.maxLocalError=Math.Max(pr.maxLocalError,local);var mw=pr.meshLocalToWorld;double wx=mw.m00*dx+mw.m01*dy+mw.m02*dz,wy=mw.m10*dx+mw.m11*dy+mw.m12*dz,wz=mw.m20*dx+mw.m21*dy+mw.m22*dz,error=Math.Sqrt(wx*wx+wy*wy+wz*wz);var world=mw.MultiplyPoint3x4(new Vector3(got.x,got.y,got.z));lo=Vector3.Min(lo,world);hi=Vector3.Max(hi,world);pr.maxRestDisplacementM=Math.Max(pr.maxRestDisplacementM,Vector3.Distance(world,mw.MultiplyPoint3x4(new Vector3(q.x,q.y,q.z))));if(double.IsNaN(error)||double.IsInfinity(error)||got.w!=1)throw new Exception("Nonfinite GPU output "+v);if(error>pr.maxErrorM){pr.maxErrorM=error;pr.worstOriginalId=v;}}
 pr.worldSpan=hi-lo;if(pr.worldSpan.y<.2f||pr.worldSpan.y>2f||pr.maxRestDisplacementM<.01f)throw new Exception("Invalid physical size/static pose witness");r.poses.Add(pr);Debug.Log("Native67 GPU pose "+pr.clip+" max "+pr.maxErrorM);if(pr.maxErrorM>1e-6)throw new Exception("Predeclared 1um GPU position gate exceeded");}
 r.status="FULL_FLOAT_GPU_POSITION_REVIEW_PASS_PENDING_RENDERER";exit=0;
 }catch(Exception e){r.status="FAILED_NO_PROMOTION";r.error=e.ToString();Debug.LogException(e);}finally{foreach(var b in buffers)b.Dispose();if(instance!=null)UnityEngine.Object.DestroyImmediate(instance);File.WriteAllText(Environment.GetEnvironmentVariable("LF_NATIVE67_REPORT"),JsonUtility.ToJson(r,true));Debug.Log("AGENT_RESULT "+r.status);EditorApplication.Exit(exit);}}
}
